import java.util.ArrayList;
import java.util.List;

public class ProjectProperties {
  protected String label = "Issue Number";
  protected String message;
  protected boolean number = false;
  protected String url;
  protected boolean warnIfNoIssue = false;
  protected boolean append = true;
  protected String logregex;
  private static final String URL = "://"; // $NON-NLS-1$
  private static final List<String> propertyFilterList = new ArrayList<>();
  static {
    propertyFilterList.add("bugtraq:message");
    propertyFilterList.add("bugtraq:label");
    propertyFilterList.add("bugtraq:url");
    propertyFilterList.add("bugtraq:number");
    propertyFilterList.add("bugtraq:warnifnoissue");
    propertyFilterList.add("bugtraq:append");
    propertyFilterList.add("bugtraq:logregex");
  }

  public ProjectProperties() {
    super();
  }

  public boolean isAppend() {
    return append;
  }

  public void setAppend(boolean append) {
    this.append = append;
  }

  public String getLabel() {
    return label;
  }

  public void setLabel(String label) {
    this.label = label;
  }

  public String getMessage() {
    return message;
  }

  public void setMessage(String message) {
    this.message = message;
  }

  public boolean isNumber() {
    return number;
  }

  public void setNumber(boolean number) {
    this.number = number;
  }

  public String getUrl() {
    return url;
  }

  public void setUrl(String url) {
    this.url = url;
  }

  public boolean isWarnIfNoIssue() {
    return warnIfNoIssue;
  }

  public void setWarnIfNoIssue(boolean warnIfNoIssue) {
    this.warnIfNoIssue = warnIfNoIssue;
  }

  public String getLogregex() {
    return logregex;
  }

  public void setLogregex(String logregex) {
    this.logregex = logregex;
  }

  public String getResolvedMessage(String issue) {
    if (message == null || issue == null) {
      return null;
    }
    return message.replace("%BUGID%", issue);
  }

  public String getResolvedUrl(String issue) {
    if (url == null || issue == null) {
      return null;
    }
    return url.replace("%BUGID%", issue);
  }

  public LinkList getLinkList(String commitMessage) {
    List<LinkList> linkList = new ArrayList<>();
    List<String> urls = new ArrayList<>();
    List<String> texts = new ArrayList<>();
    List<String> texts2 = new ArrayList<>();

    String bugID = "%BUGID%";
    String logRegex = getLogregex();

    if (logRegex != null) {
      String[] resplit = logRegex.split("\n");
      String re1 = resplit[0].trim();
      String re2 = resplit.length > 1 ? resplit[1].trim() : null;

      Pattern pre1 = Pattern.compile(re1);
      Matcher matcher1 = pre1.matcher(commitMessage);
      if (re2 != null) {
        Pattern pre2 = Pattern.compile(re2);
        Matcher matcher2 = pre2.matcher(matcher1.group());
        while (matcher2.find()) {
          String url = getResolvedUrl(matcher2.group());
          if (url != null && url.length() > 0) {
            urls.add(url);
            texts.add(matcher2.group());
          }
        }
      } else {
        while (matcher1.find()) {
          String url = getResolvedUrl(matcher1.group());
          if (url != null && url.length() > 0) {
            urls.add(url);
            texts.add(matcher1.group());
          }
        }
      }
    } else {
      if (message != null) {
        int index = message.indexOf(bugID);
        if (index != -1) {
          String remainder = message.substring(index + bugID.length());
          String tag = message.substring(0, index);
          int start = index;
          StringBuffer issueText = new StringBuffer();
          int i = 0;
          while (i < commitMessage.length()) {
            if (commitMessage.charAt(i) == ',' && i < commitMessage.length()) {
              int range[] = {start, issueText.length()};
              String url = getResolvedUrl(issueText.toString());
              if (url != null && url.length() > 0) {
                urls.add(url);
                texts.add(issueText.toString());
              }
              start = i + 1;
              issueText = new StringBuffer();
            } else if (i < commitMessage.length() && commitMessage.charAt(i) == '\n' || commitMessage.charAt(i) == '\r') {
              i++;
              continue;
            } else {
              issueText.append(commitMessage.charAt(i));
            }
            i++;
          }
          int range[] = {start, issueText.length()};
          String url = getResolvedUrl(issueText.toString());
          if (url != null && url.length() > 0) {
            urls.add(url);
            texts.add(issueText.toString());
          }
        }
      }
    }

    LinkList linkList = new LinkList(urls, texts, texts2);
    return linkList;
  }

  private String getResolvedUrl(String text) {
    if (text == null || text.trim().isEmpty()) {
      return null;
    }
    return text;
  }
