static class UnitOrders
{
    static Player FindPlayerByClient(World world, Session.Client client)
    {
        return world.Players.FirstOrDefault(p => p.ClientIndex == client.Index && p.PlayerReference.Playable);
    }

    static void ProcessOrder(OrderManager orderManager, World world, int clientId, Order order)
    {
        if (world != null)
        {
            if (orderManager.TraitsImplementing<IValidateOrder>().All(vo => vo.OrderValidation(order, world, clientId)))
            {
                return;
            }

            switch (order.OrderString)
            {
                case "Chat":
                    {
                        var client = orderManager.LobbyInfo.ClientWithIndex(clientId);
                        if (client != null)
                        {
                            var player = world.FindPlayerByClient(client);
                            var suffix = player != null && player.WinState == WinState.Lost ? " (Dead)" : "";
                            Game.AddChatLine(client.Color.RGB, client.Name + suffix, order.TargetString);
                        }
                        else
                        {
                            Game.AddChatLine(Color.White, " (player {0})".F(clientId), order.TargetString);
                        }
                        break;
                    }

                case "Message":
                    {
                        Game.AddChatLine(Color.White, "Server", order.TargetString);
                        break;
                    }

                case "Disconnected":
                    {
                        var client = orderManager.LobbyInfo.ClientWithIndex(clientId);
                        if (client != null)
                        {
                            client.State = Session.ClientState.Disconnected;
                        }
                        break;
                    }

                case "TeamChat":
                    {
                        var client = orderManager.LobbyInfo.ClientWithIndex(clientId);
                        if (client != null)
                        {
                            var player = world.FindPlayerByClient(client);
                            var suffix = player != null && player.WinState == WinState.Lost ? " (Dead)" : " (Team)";
                            Game.AddChatLine(client.Color.RGB, client.Name + suffix, order.TargetString);
                        }
                        break;
                    }

                case "StartGame":
                    {
                        Game.AddChatLine(Color.White, "Server", "The game has started.");
                        Game.StartGame(orderManager.LobbyInfo.GlobalSettings.Map, false);
                        break;
                    }

                case "PauseGame":
                    {
                        var client = orderManager.LobbyInfo.ClientWithIndex(clientId);
                        if (client != null)
                        {
                            client.State = Session.ClientState.Paused;
                        }
                        break;
                    }

                case "HandshakeRequest":
                    {
                        // TODO: Switch to server's mod if available
                        var mod = Game.modData.Manifest.Mod;
                        var info = new Session.Client
                        {
                            Name = Game.Settings.Player.Name,
                            Color = Game.Settings.Player.Color,
                            Country = "random",
                            Team = 0,
                            State = Session.ClientState.Invalid
                        };
                        var response = new HandshakeResponse
                        {
                            Client = info,
                            Mod = mod.Id,
                            Version = mod.Version,
                            Password = order.Password
                        };
                        orderManager.IssueOrder(HandshakeResponse.Serialize(response));
                        break;
                    }

                case "ServerError":
                    {
                        orderManager.ServerError = order.TargetString;
                        orderManager.AuthenticationFailed = true;
                        break;
                    }

                case "AuthenticationError":
                    {
                        orderManager.ServerError = order.TargetString;
                        orderManager.AuthenticationFailed = true;
                        break;
                    }

                case "SyncInfo":
                    {
                        orderManager.LobbyInfo = Session.Deserialize(order.TargetString);
                        SetOrderLag(orderManager);
                        Game.SyncLobbyInfo();
                        break;
                    }

                case "SyncLobbyClients":
                    {
                        var clients = new List<Session.Client>();
                        var nodes = MiniYaml.FromString(order.TargetString);
                        foreach (var node in nodes)
                        {
                            var strings = node.Key.Split('@');
                            if (strings[0] == "Client")
                            {
                                clients.Add(Session.Client.Deserialize(node.Value));
                            }
                        }
                        orderManager.LobbyInfo.Clients = clients;
                        Game.SyncLobbyInfo();
                        break;
                    }

                case "SyncLobbySlots":
                    {
                        var slots = new Dictionary<string, Session.Slot>();
                        var nodes = MiniYaml.FromString(order.TargetString);
                        foreach (var node in nodes)
                        {
                            var strings = node.Key.Split('@');
                            if (strings[0] == "Slot")
                            {
                                var slot = Session.Slot.Deserialize(node.Value);
                                slots.Add(slot.PlayerReference, slot);
                            }
                        }
                        orderManager.LobbyInfo.Slots = slots;
                        Game.SyncLobbyInfo();
                        break;
                    }
            }
        }
    }
