import os
import warnings
import numpy as np
from photon_tools.io import timetag_parse, pt2_parse, metadata

time_ch_dtype = np.dtype([('time', 'u8'), ('chan', 'u1')])

def verify_monotonic(times, filename):
    if len(times) == 0:
        return
    negatives = times[1:] <= times[:-1]
    if np.count_nonzero(negatives) > 0:
        warnings.warn(f"{filename}: Found {np.count_nonzero(negatives)} non-monotonic timestamps: photon indices {np.where(negatives)[0]}")

def verify_continuity(times, filename, gap_factor=1000):
    if len(times) == 0:
        return
    tau = (times[-1] - times[0]) / len(times)
    gaps = (times[1:] - times[:-1]) > gap_factor * tau
    if np.count_nonzero(gaps) > 0:
        starts = np.nonzero(gaps)
        for s in starts:
            msg = f"{filename}: Found {np.count_nonzero(gaps)} large gaps: starting at {s}, ending at {times[s]} (duration {times[s+1] - times[s]})"
            print(msg)

class InvalidChannel(ValueError):
    def __init__(self, requested_channel, valid_channels):
        super().__init__(f"Channel {requested_channel} was requested but this file only supports channels {valid_channels}")

class TimestampFile:
    def __init__(self, filename, jiffy=None):
        self._filename = filename
        self._jiffy = jiffy

    @property
    def jiffy(self):
        return self._jiffy

    @property
    def valid_channels(self):
        return self._valid_channels

    @property
    def metadata(self):
        return self._metadata

    @property
    def name(self):
        return self._filename

    def read(self, channel=None):
        if channel is None:
            return self._read_all()
        self._validate_channel(channel)
        return self._read_channel(channel)

    def _read_all(self):
        data = np.fromfile(self._filename, dtype=np.dtype(time_ch_dtype))
        return data

    def _read_channel(self, channel):
        data = np.fromfile(self._filename, dtype=np.dtype(time_ch_dtype))
        return data[data[channel] == 1]

    def _validate_channel(self, channel):
        if channel not in self.valid_channels:
            raise InvalidChannel(channel, self.valid_channels)

readers = [
    PicoquantFile,
    TimetagFile,
    RawFile,
    RawChFile
]

def supported_extensions():
    extensions = {}
    for reader in readers:
        for ext in reader.extensions:
            extensions[ext] = reader
    return extensions

def find_reader(fname):
    return readers[find_index(fname)]
