    public void addAScore(PlayerScore score) {
        if (this.rounds.size() > 1) {
            for (PlayerScore eachPlayerScore : this.scoreTable) {
                if (eachPlayerScore.getPlayer().getId().equals(score.getPlayer().getId())) {
                    for (int i = 0; i < eachPlayerScore.getScore().size(); i++) {
                        eachPlayerScore.getScore().set(i, eachPlayerScore.getScore().get(i) + score.getScore().get(i));
                    }
                }
            }
        } else {
            this.scoreTable.add(score);
        }
    }

    public void removeAScore(PlayerScore score) {
        if (this.rounds.size() > 1) {
            for (PlayerScore eachPlayerScore : this.scoreTable) {
                if (eachPlayerScore.getPlayer().getId().equals(score.getPlayer().getId())) {
                    for (int i = 0; i < eachPlayerScore.getScore().size(); i++) {
                        eachPlayerScore.getScore().set(i, eachPlayerScore.getScore().get(i) - score.getScore().get(i));
                    }
                }
            }
        } else {
            this.scoreTable.remove(score);
        }
    }
```

