    {
        public GenericCallback(T value)
        {
            _value = value;
        }

        public void response(T value)
        {
            _value = value;
            _succeeded = true;
            called();
        }

        public void exception(Ice.Exception ex)
        {
            _succeeded = false;
            called();
        }

        public bool succeeded()
