// gui.cs: Simple curses-based GUI toolkit, core

using System;
using System.Collections.Generic;
using System.IO;
using CursesSharp;

namespace CursesSharp.Gui {

	/// <summary>
	///   Base class for creating curses widgets
	/// </summary>
	[Flags]
	public abstract class Widget {
		Container Container;
		int x, y, w, h;
		bool can_focus;
		bool has_focus;
		public Fill Fill;
		static StreamWriter l;
		// Utility functions to log messages
		// This is a utility function that you can use to log messages
		// The data is written to the file "log2" for now
		public static void Log (string s) {
			if (l == null) {
				l = new StreamWriter (File.Create ("log2"));
			}
			l.WriteLine (s);
			l.Flush ();
		}
		public static void Log (string s, params object [] args) {
			Log (String.Format (s, args));
		}
		// Utility function to draw frames
		// Draws a frame with the current color in the specified coordinates
		// This is a helper routine that positions the cursor at the beginning of the widget
		// The default implementation puts the cursor at the beginning, but derived classes should find a suitable spot
		// for the cursor to be shown
		static public void DrawFrame (int col, int line, int width, int height, bool fill) {
			Stdscr.Move (line, col);
			Stdscr.Add (Acs.Ulcorner);
			for (int b = 0; b < width - 2; b++) {
				Stdscr.Add (Acs.Hline);
			}
			Stdscr.Add (Acs.Urcorner);
			for (int b = 1; b < height - 1; b++) {
				Stdscr.Move (line + b, col);
				Stdscr.Add (Acs.Vline);
				if (fill) {
					for (int x = 1; x < width - 1; x++) {
						Stdscr.Add (' ');
					}
				} else {
					Stdscr.Move (line + b, col + width - 1);
				}
				Stdscr.Add (Acs.Vline);
			}
			Stdscr.Move (line + height - 1, col);
			Stdscr.Add (Acs.Lcorner);
			for (int b = 0; b < width - 2; b++) {
				Stdscr.Add (Acs.Hline);
			}
			Stdscr.Add (Acs.Lrcorner);
		}
		// Utility function to draw strings with hotkey
		// Draws a string with the given color. If a character "_" is found, the next character is drawn using the hotcolor
		// This is a helper routine that positions the cursor at the beginning of the widget
		// The default implementation puts the cursor at the beginning, but derived classes should find a suitable spot
		// for the cursor to be shown
		static public void DrawHotString (string s, uint color, uint hotcolor) {
			Stdscr.Attr = color;
			for (int c = 0; c < s.Length; c++) {
				if (s[c] == '_') {
					Stdscr.Attr = hotcolor;
					continue;
				}
				Stdscr.Add (s[c]);
			}
		}
