```csharp
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

namespace TagLib.Id3v2
{
    public class TextInformationFrame : Frame
    {
        #region Private Fields

        private StringType encoding = Id3v2.Tag.DefaultEncoding;

        private string[] text_fields = new string[0];

        private ByteVector raw_data = null;

        private byte raw_version = 0;

        private StringType raw_encoding = StringType.Latin1;

        #endregion

        #region Constructors

        public TextInformationFrame(ByteVector ident, StringType encoding)
            : base(ident, 4)
        {
            this.encoding = encoding;
        }

        public TextInformationFrame(ByteVector ident)
            : this(ident, Id3v2.Tag.DefaultEncoding)
        {
        }

        public TextInformationFrame(ByteVector ident, byte version)
            : this(ident, Id3v2.Tag.DefaultEncoding)
        {
            raw_version = version;
        }

        #endregion

        #region Public Properties

        public StringType Encoding
        {
            get
            {
                if (raw_encoding == StringType.Latin1)
                    return encoding;

                return StringType.Latin1;
            }
            set
            {
                raw_encoding = value;
            }
        }

        public string[] Text
        {
            get
            {
                if (raw_data == null)
                    return new string[0];

                string[] result = new string[raw_data.Length];
                int i = 0;

                for (int j = 0; j < raw_data.Length; j++)
                {
                    result[i] = raw_data[j];
                    i++;
                }

                return result;
            }
        }

        public string Description
        {
            get
            {
                if (text_fields.Length == 0)
                    return string.Empty;

                return text_fields[0];
            }
        }

        #endregion

        #region Public Methods

        public override string ToString()
        {
            return new StringBuilder()
                .Append("TextInformationFrame {")
                .Append("Encoding: ").Append(encoding)
                .Append(", Text: ").Append(string.Join(", ", Text))
                .Append("}")
                .ToString();
        }

        #endregion
    }
}
