        class KeywordEntry
        {
            public readonly int Token;
            public readonly char[] Value;
            public readonly char[] Next;
            public KeywordEntry(char[] value, int token)
            {
                this.Value = value;
                this.Token = token;
            }
        }

        class KeywordEntry<T>
        {
            public readonly T Token;
            public KeywordEntry<T> Next;
            public readonly char[] Value;
            public KeywordEntry(char[] value, T token)
            {
                this.Value = value;
                this.Token = token;
            }
        }

        class IdentifiersComparer : IEqualityComparer<char[]>
        {
            readonly int Length;
            public IdentifiersComparer(int length)
            {
                this.Length = length;
            }

            public bool Equals(char[] x, char[] y)
            {
                for (int i = 0; i < Length; i++)
                {
                    if (x[i] != y[i])
                        return false;
                }
                return true;
            }

            public int GetHashCode(char[] obj)
            {
                int h = 0;
                for (int i = 0; i < Length; i++)
                {
                    h = (h << 5) - h + obj[i];
                }
                return h;
            }
        }

