            {
                LocatedToken entry;
                if (pos >= buffer.Length)
                {
                    entry = new LocatedToken();
                    buffer[pos] = entry;
                    pos++;
                } else
                {
                    entry = buffer[pos];
                    buffer[pos] = new LocatedToken();
                }
                entry.row = row;
                entry.column = column;
                return entry;
            }

