                bitsColorDepth = System.Drawing.Imaging.PixelFormat.Format8bppIndexed;
            System.Drawing.Imaging.ColorPalette palette;
            System.Drawing.Bitmap bitmap = new Bitmap(1, 1, bitsColorDepth);
            palette = bitmap.Palette;
            bitmap.Dispose();
            return palette;
