        public static bool[,] RemoveSolitaryPixels(bool[,] binaryImage, int minimumMatches)
        {
            int width = binaryImage.GetLength(0);
            int height = binaryImage.GetLength(1);
            bool[,] result = new bool[width, height];
            for (int x = 1; x < width - 1; x++)
            {
                for (int y = 1; y < height - 1; y++)
                {
                    bool state = binaryImage[x, y];
                    result[x, y] = state;
                    int opposingPixelCount = 0;
                    int xx = x - 1;
                    while ((xx <= x + 1) && (opposingPixelCount < minimumMatches))
                    {
                        int yy = y - 1;
                        while ((yy <= y + 1) && (opposingPixelCount < minimumMatches))
                        {
                            if (binaryImage[xx, yy] != state)
                                opposingPixelCount++;
                            yy++;
                        }
                        xx++;
                    }
                    if (opposingPixelCount > minimumMatches)
                        result[x, y] = !state;
                }
            }
            return result;
