    return path_sep.join([part.rstrip(path_sep) for part in path_parts])

def _path_split(path):
    """Replacement for os.path.split()."""
    if len(path_sep) == 1:
        front, tail = path.rpartition(path_sep)
        return front, tail
    for x in reversed(path):
        if x in path_sep:
            front, tail = path.rpartition(x)
            return front, tail
    return path, ''

