    /// </summary>
    internal partial class Binder
    {
        /// <summary>
        /// This is the set of parameters and local variables that were used as arguments to lock or using statements in enclosing scopes.
        /// </summary>
        internal virtual ImmutableHashSet<Symbol> LockedOrDisposedVariables
        {
            get { return this.next.LockedOrDisposedVariables; }
