class BibRecDocs:
    """
    This class represents all the files attached to a record.
    """
    def __init__(self, recid, deleted_too=False, human_readable=False):
        self.id = recid
        self.human_readable = human_readable
        self.deleted_too = deleted_too
        self.bibdocs = []
        self.build_bibdoc_list()

    def __repr__(self):
        """
        Returns a canonical string representation of the BibRecDocs object.
        """
        return "BibRecDocs(%s, %s, %s)" % (self.id, self.human_readable, self.deleted_too)

    def __str__(self):
        """
        Returns a human-readable string representation of the BibRecDocs object.
        """
        return "BibRecDocs with %s attached" % len(self.bibdocs)

    def build_bibdoc_list(self):
        """
        Builds the list of documents attached to the record.
        """
        self.bibdocs = []
        if self.deleted_too:
            res = run_sql("SELECT id, type FROM bibrec_bibdoc WHERE id_bibrec = %s ORDER BY docname ASC" % self.id)
        else:
            res = run_sql("SELECT id, type FROM bibrec_bibdoc WHERE id_bibrec = %s AND status != 'DELETED' ORDER BY docname ASC" % self.id)
        for row in res:
            doc = BibDoc(docid=row[0], recid=self.id, doctype=row[1], human_readable=self.human_readable)
            self.bibdocs.append(doc)

    def get_bibdoc(self, docid):
        """
        Returns a BibDoc object for a given docid.
        """
        for doc in self.bibdocs:
            if doc.docid == docid:
                return doc
        return None

    def get_bibdocs(self):
        """
        Returns a list of all BibDoc objects attached to the record.
        """
        return self.bibdocs

    def get_total_size(self):
        """
        Returns the total size of all files attached to the record.
        """
        total_size = 0
        for doc in self.bibdocs:
            total_size += doc.get_total_size()
        return total_size

